Use a circular buffer with a separate element count, so all 17 slots are usable and overflow is rejected without modifying the queue. The invariant is that count stays between 0 and 17, head identifies the next item to pop, and tail equals (head + count) modulo 17. Head and tail coincide in both the empty and full states; count distinguishes them: 0 means empty, and 17 means full.

```cpp
#include <array>
#include <cassert>
#include <cstddef>
#include <iostream>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (count_ == capacity) {
            return false; // No state or contents are changed.
        }
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++count_;
        return true;
    }

    bool pop(int& value) {
        if (count_ == 0) {
            return false; // Output argument is also unchanged.
        }
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --count_;
        return true;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

int main() {
    BoundedFIFO queue;
    int value = -1;

    // Empty pop fails without changing the output.
    assert(queue.empty());
    assert(!queue.pop(value));
    assert(value == -1);

    // All 17 slots are usable.
    for (int i = 0; i < 17; ++i) {
        assert(queue.push(i));
        assert(queue.size() == static_cast<std::size_t>(i + 1));
    }
    assert(queue.full());

    // The 18th insertion is rejected; draining verifies contents.
    assert(!queue.push(999));
    assert(queue.size() == 17);
    for (int i = 0; i < 17; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.empty());
    assert(!queue.pop(value));

    // Wraparound with live items still in the buffer.
    for (int i = 0; i < 17; ++i) {
        assert(queue.push(100 + i));
    }
    for (int i = 0; i < 10; ++i) {
        assert(queue.pop(value));
        assert(value == 100 + i);
    }
    // These writes wrap and reuse the ten freed slots.
    for (int i = 0; i < 10; ++i) {
        assert(queue.push(117 + i));
    }
    assert(queue.full());
    assert(!queue.push(999));
    for (int expected = 110; expected <= 126; ++expected) {
        assert(queue.pop(value));
        assert(value == expected);
    }
    assert(queue.empty());
    assert(!queue.pop(value));

    std::cout << "All tests passed\n";
}
```

